    function previewRedeem(uint256 basketId, address stable, uint256 tokenAmount)
        external
        view
        returns (uint256 stableOut, uint256 fee)
    {
        RedeemQuote memory q = quoteRedeem(basketId, stable, tokenAmount);
        return (q.payoutNow, q.feeNow);
